const form=document.getElementById("compoundForm"),result=document.getElementById("result");form&&form.addEventListener("submit",l=>{l.preventDefault();const t=parseFloat(document.getElementById("principal").value)||0,n=parseFloat(document.getElementById("monthly").value)||0,c=parseFloat(document.getElementById("rate").value)||0,i=parseInt(document.getElementById("months").value,10)||0;if(t<0||n<0||c<0||i<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите корректные значения.</p>';return}const e=c/100/12,s=i;let a;e===0?a=t+n*s:a=t*Math.pow(1+e,s)+n*((Math.pow(1+e,s)-1)/e);const o=t+n*s,m=a-o;result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Вложено всего</span><span class="val">${fmt(o)} ₽</span></div>
        <div class="item"><span>Итоговая сумма</span><span class="val">${fmt(a)} ₽</span></div>
        <div class="item total"><span>Доход</span><span class="val">${fmt(m)} ₽ (${fmt(m/o*100)}%)</span></div>
      </div>
    `});function fmt(l){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(l)}
